62	// WriteCommittedMainBatch writes /main entries for every (checkpoint, session)
63	// pair in batch using a single commit and a single ref CAS. The /full ref is
64	// left untouched — callers handle full-transcript artifacts via the existing
65	// pack flow. Returns session indexes parallel to batch.
66	//
67	// Matches per-session writeCommittedMain semantics within each checkpoint
68	// group: existing-SessionID dedupe, slot-0 refuse-overwrite, last non-nil
69	// combinedAttribution, and sticky HasReview.
70	func (s *V2GitStore) WriteCommittedMainBatch(ctx context.Context, batch []WriteCommittedOptions) ([]int, error) {
71		if len(batch) == 0 {
72			return nil, nil
73		}
74		for i, opts := range batch {
75			if err := validateWriteOpts(opts); err != nil {
76				return nil, fmt.Errorf("batch entry %d: %w", i, err)
77			}
78		}
79	
80		refName := plumbing.ReferenceName(paths.V2MainRefName)
81		if err := s.ensureRef(ctx, refName); err != nil {
82			return nil, fmt.Errorf("failed to ensure /main ref: %w", err)
83		}
84		parentHash, rootTreeHash, err := s.GetRefState(refName)
85		if err != nil {
86			return nil, err
87		}
88	
89		type cpGroup struct {
90			cpID     id.CheckpointID
91			ordinals []int
92		}
93		groups := []*cpGroup{}
94		byID := map[id.CheckpointID]*cpGroup{}
95		for i, opts := range batch {
96			g, ok := byID[opts.CheckpointID]
97			if !ok {
98				g = &cpGroup{cpID: opts.CheckpointID}
99				byID[opts.CheckpointID] = g
100				groups = append(groups, g)
101			}
102			g.ordinals = append(g.ordinals, i)
103		}
104	
105		sessionIndexes := make([]int, len(batch))
106		existingCheckpoints, err := s.existingMainCheckpointIDs(rootTreeHash)
107		if err != nil {
108			return nil, err
109		}
110		changes := make([]TreeChange, 0, len(groups))
111		for _, g := range groups {
112			var checkpointTreeHash plumbing.Hash
113			if _, exists := existingCheckpoints[g.cpID]; exists {
114				checkpointTreeHash, err = s.buildMainBatchGroupTree(ctx, rootTreeHash, g.cpID, g.ordinals, batch, sessionIndexes)
115			} else {
116				checkpointTreeHash, err = s.buildFreshMainBatchGroupTree(ctx, g.cpID, g.ordinals, batch, sessionIndexes)
117			}
118			if err != nil {
119				return nil, err
120			}
121			changes = append(changes, TreeChange{
122				Path: g.cpID.Path(),
123				Entry: &object.TreeEntry{
124					Mode: filemode.Dir,
125					Hash: checkpointTreeHash,
126				},
127			})
128		}
129		if len(changes) > 0 {
130			rootTreeHash, err = ApplyTreeChanges(ctx, s.repo, rootTreeHash, changes)
131			if err != nil {
132				return nil, fmt.Errorf("failed to apply batched /main checkpoint trees: %w", err)
133			}
134		}
135	
136		// One commit, one ref update for the entire batch.
137		commitMsg := fmt.Sprintf("Migrate batch: %d checkpoint(s), %d session(s)\n", len(groups), len(batch))
138		last := batch[len(batch)-1]
139		authorName, authorEmail := last.AuthorName, last.AuthorEmail
140		if authorName == "" || authorEmail == "" {
141			fallbackName, fallbackEmail := GetGitAuthorFromRepo(s.repo)
142			if authorName == "" {
143				authorName = fallbackName
144			}
145			if authorEmail == "" {
146				authorEmail = fallbackEmail
147			}
148		}
149		if err := s.updateRef(ctx, refName, rootTreeHash, parentHash, commitMsg, authorName, authorEmail); err != nil {
150			return nil, err
151		}
152		return sessionIndexes, nil
153	}
