155	func (s *V2GitStore) existingMainCheckpointIDs(rootTreeHash plumbing.Hash) (map[id.CheckpointID]struct{}, error) {
156		existing := make(map[id.CheckpointID]struct{})
157		if rootTreeHash == plumbing.ZeroHash {
158			return existing, nil
159		}
160		rootTree, err := s.repo.TreeObject(rootTreeHash)
161		if err != nil {
162			return nil, fmt.Errorf("failed to read /main root tree: %w", err)
163		}
164		if err := WalkCheckpointShards(s.repo, rootTree, func(cpID id.CheckpointID, _ plumbing.Hash) error {
165			existing[cpID] = struct{}{}
166			return nil
167		}); err != nil {
168			return nil, fmt.Errorf("failed to walk existing /main checkpoints: %w", err)
169		}
170		return existing, nil
171	}
