173	func (s *V2GitStore) buildFreshMainBatchGroupTree(ctx context.Context, cpID id.CheckpointID, ordinals []int, batch []WriteCommittedOptions, sessionIndexes []int) (plumbing.Hash, error) {
174		basePath := cpID.Path() + "/"
175		entries := make(map[string]object.TreeEntry)
176		sessions := make([]SessionFilePaths, len(ordinals))
177	
178		for sessionIndex, ordinal := range ordinals {
179			opts := batch[ordinal]
180			sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
181			filePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
182			if err != nil {
183				return plumbing.ZeroHash, err
184			}
185			sessions[sessionIndex] = filePaths
186			sessionIndexes[ordinal] = sessionIndex
187		}
188	
189		lastOpts := batch[ordinals[len(ordinals)-1]]
190		if err := s.writeFreshMainBatchCheckpointSummary(lastOpts, basePath, entries, sessions, ordinals, batch); err != nil {
191			return plumbing.ZeroHash, err
192		}
193		return s.buildCheckpointSubtree(ctx, basePath, entries)
194	}
