196	func (s *V2GitStore) writeFreshMainBatchCheckpointSummary(lastOpts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, sessions []SessionFilePaths, ordinals []int, batch []WriteCommittedOptions) error {
197		var checkpointsCount int
198		var filesTouched []string
199		var tokenUsage *agent.TokenUsage
200		var combinedAttribution *InitialAttribution
201		var hasReview bool
202		for _, ordinal := range ordinals {
203			opts := batch[ordinal]
204			checkpointsCount += opts.CheckpointsCount
205			filesTouched = mergeFilesTouched(filesTouched, opts.FilesTouched)
206			tokenUsage = aggregateTokenUsage(tokenUsage, opts.TokenUsage)
207			if opts.CombinedAttribution != nil {
208				combinedAttribution = opts.CombinedAttribution
209			}
210			hasReview = hasReview || opts.HasReview
211		}
212	
213		summary := CheckpointSummary{
214			CheckpointID:        lastOpts.CheckpointID,
215			CLIVersion:          versioninfo.Version,
216			Strategy:            lastOpts.Strategy,
217			Branch:              lastOpts.Branch,
218			CheckpointsCount:    checkpointsCount,
219			FilesTouched:        filesTouched,
220			Sessions:            sessions,
221			TokenUsage:          tokenUsage,
222			CombinedAttribution: combinedAttribution,
223			HasReview:           hasReview,
224		}
225	
226		metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
227		if err != nil {
228			return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
229		}
230		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
231		if err != nil {
232			return err
233		}
234		entries[basePath+paths.MetadataFileName] = object.TreeEntry{
235			Name: basePath + paths.MetadataFileName,
236			Mode: filemode.Regular,
237			Hash: metadataHash,
238		}
239		return nil
240	}
