242	// buildMainBatchGroupTree writes every session in one checkpoint group into an
243	// isolated checkpoint subtree. WriteCommittedMainBatch splices all returned
244	// checkpoint trees into /main in one pass, instead of rewriting the root and
245	// shard trees once per checkpoint.
246	func (s *V2GitStore) buildMainBatchGroupTree(ctx context.Context, rootTreeHash plumbing.Hash, cpID id.CheckpointID, ordinals []int, batch []WriteCommittedOptions, sessionIndexes []int) (plumbing.Hash, error) {
247		basePath := cpID.Path() + "/"
248		checkpointPath := cpID.Path()
249	
250		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
251		if err != nil {
252			return plumbing.ZeroHash, err
253		}
254	
255		var existingSummary *CheckpointSummary
256		if entry, exists := entries[basePath+paths.MetadataFileName]; exists {
257			if existing, readErr := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash); readErr == nil {
258				existingSummary = existing
259			}
260		}
261	
262		// Track the sessions slice as we write so writeCheckpointSummary at the
263		// end of the group sees a complete picture and findSessionIndex on later
264		// entries in the group can dedupe against earlier ones.
265		var sessions []SessionFilePaths
266		if existingSummary != nil {
267			sessions = make([]SessionFilePaths, len(existingSummary.Sessions))
268			copy(sessions, existingSummary.Sessions)
269		}
270	
271		for _, ordinal := range ordinals {
272			opts := batch[ordinal]
273	
274			// findSessionIndex needs a summary whose Sessions length reflects
275			// what we've written so far in this group.
276			runningSummary := existingSummary
277			if len(sessions) > 0 {
278				runningSummary = &CheckpointSummary{Sessions: sessions}
279			}
280			sessionIndex := s.gs.findSessionIndex(ctx, basePath, runningSummary, entries, opts.SessionID)
281	
282			if sessionIndex == 0 {
283				if entry, exists := entries[fmt.Sprintf("%s0/%s", basePath, paths.MetadataFileName)]; exists {
284					if existingMeta, readErr := s.gs.readMetadataFromBlob(entry.Hash); readErr == nil && existingMeta.SessionID != opts.SessionID {
285						logging.Error(ctx, "refusing v2 checkpoint write: session 0 holds a different sessionID",
286							slog.String("checkpoint_id", opts.CheckpointID.String()),
287							slog.String("existing_session_id", existingMeta.SessionID),
288							slog.String("write_session_id", opts.SessionID),
289							slog.Bool("existing_summary_nil", existingSummary == nil))
290						return plumbing.ZeroHash, fmt.Errorf(
291							"refusing to overwrite session 0 of checkpoint %s: existing session ID %q differs from write session ID %q. The v2 checkpoint tree is inconsistent (session 0 belongs to a different session than this write claims). No automated repair exists for this shape — please report it along with the output of `git ls-tree %s %s/`",
292							opts.CheckpointID, existingMeta.SessionID, opts.SessionID, paths.V2MainRefName, opts.CheckpointID.Path(),
293						)
294					}
295				}
296			}
297	
298			sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
299			filePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
300			if err != nil {
301				return plumbing.ZeroHash, err
302			}
303	
304			if sessionIndex >= len(sessions) {
305				grown := make([]SessionFilePaths, sessionIndex+1)
306				copy(grown, sessions)
307				sessions = grown
308			}
309			sessions[sessionIndex] = filePaths
310			sessionIndexes[ordinal] = sessionIndex
311		}
312	
313		// Last write wins for combinedAttribution / HasReview, matching the
314		// behavior of N sequential writeCommittedMain calls where each rewrites
315		// the summary blob.
316		lastOpts := batch[ordinals[len(ordinals)-1]]
317		if err := s.gs.writeCheckpointSummary(lastOpts, basePath, entries, sessions); err != nil {
318			return plumbing.ZeroHash, err
319		}
320	
321		return s.buildCheckpointSubtree(ctx, basePath, entries)
322	}
323	
324	func (s *V2GitStore) buildCheckpointSubtree(ctx context.Context, basePath string, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
325		relEntries := make(map[string]object.TreeEntry, len(entries))
326		for path, entry := range entries {
327			relPath := strings.TrimPrefix(path, basePath)
328			if relPath == path {
329				continue
330			}
331			relEntries[relPath] = entry
332		}
333	
334		checkpointTreeHash, err := BuildTreeFromEntries(ctx, s.repo, relEntries)
335		if err != nil {
336			return plumbing.ZeroHash, fmt.Errorf("failed to build checkpoint subtree: %w", err)
337		}
338		return checkpointTreeHash, nil
339	}
