341	// UpdateCommitted replaces the prompts and/or transcript for an existing v2
342	// checkpoint. Called at stop time to finalize checkpoints with the complete
343	// session transcript.
344	//
345	// On /main: replaces prompts and compact transcript (if provided).
346	// On /full/*: replaces the raw transcript where the session artifacts already
347	// live, or writes to /full/current if the session has no full artifacts yet.
348	//
349	// Returns ErrCheckpointNotFound if the checkpoint doesn't exist on /main.
350	func (s *V2GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
351		if opts.CheckpointID.IsEmpty() {
352			return errors.New("invalid update options: checkpoint ID is required")
353		}
354	
355		sessionIndex, err := s.updateCommittedMain(ctx, opts)
356		if err != nil {
357			return fmt.Errorf("v2 /main update failed: %w", err)
358		}
359	
360		if opts.Transcript.Len() > 0 {
361			if err := s.updateCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
362				return fmt.Errorf("v2 /full/* update failed: %w", err)
363			}
364		}
365	
366		return nil
367	}
