369	// fullSessionArtifacts describes where a checkpoint session's raw transcript
370	// artifacts live across the v2 /full/* refs.
371	type fullSessionArtifacts struct {
372		RefName       plumbing.ReferenceName
373		Found         bool
374		HasTranscript bool
375		HasHash       bool
376	}
377	
378	// HasFullSessionArtifacts reports whether the raw transcript and content hash
379	// for a checkpoint session exist in any local v2 /full/* ref.
380	func (s *V2GitStore) HasFullSessionArtifacts(checkpointID id.CheckpointID, sessionIndex int) (bool, error) {
381		artifacts, err := s.findFullSessionArtifacts(checkpointID, sessionIndex)
382		if err != nil {
383			return false, err
384		}
385		return artifacts.Found && artifacts.HasTranscript && artifacts.HasHash, nil
386	}
387	
388	func (s *V2GitStore) findFullSessionArtifacts(checkpointID id.CheckpointID, sessionIndex int) (fullSessionArtifacts, error) {
389		refNames, err := s.fullRefSearchOrder()
390		if err != nil {
391			return fullSessionArtifacts{}, err
392		}
393	
394		var firstFound fullSessionArtifacts
395		for _, refName := range refNames {
396			artifacts, inspectErr := s.inspectFullSessionArtifacts(refName, checkpointID, sessionIndex)
397			if inspectErr != nil {
398				return fullSessionArtifacts{}, inspectErr
399			}
400			if !artifacts.Found {
401				continue
402			}
403			if artifacts.HasTranscript && artifacts.HasHash {
404				return artifacts, nil
405			}
406			if !firstFound.Found {
407				firstFound = artifacts
408			}
409		}
410	
411		if firstFound.Found {
412			return firstFound, nil
413		}
414	
415		return fullSessionArtifacts{}, nil
416	}
