418	// FullSessionArtifactsIndex answers "does this session have complete /full/*
419	// artifacts?" with an O(1) map lookup. Build it once via
420	// BuildFullSessionArtifactsIndex.
421	type FullSessionArtifactsIndex map[string]struct{}
422	
423	// Has reports whether the given session has a complete pair of
424	// raw_transcript and raw_transcript_hash.txt entries in some /full/* ref.
425	func (idx FullSessionArtifactsIndex) Has(checkpointID id.CheckpointID, sessionIndex int) bool {
426		if idx == nil {
427			return false
428		}
429		_, ok := idx[fullArtifactsIndexKey(checkpointID, sessionIndex)]
430		return ok
431	}
432	
433	func fullArtifactsIndexKey(checkpointID id.CheckpointID, sessionIndex int) string {
434		return string(checkpointID) + "/" + strconv.Itoa(sessionIndex)
435	}
436	
437	// BuildFullSessionArtifactsIndex walks every /full/* ref's tree once and
438	// records sessions whose subtree contains both raw_transcript[/.NNN] and
439	// raw_transcript_hash.txt. Amortizes per-session HasFullSessionArtifacts
440	// calls — each of which would otherwise list every git ref and re-walk every
441	// /full/* tree — across the rest of the run.
442	func (s *V2GitStore) BuildFullSessionArtifactsIndex() (FullSessionArtifactsIndex, error) {
443		refNames, err := s.fullRefSearchOrder()
444		if err != nil {
445			return nil, err
446		}
447	
448		index := make(FullSessionArtifactsIndex)
449		for _, refName := range refNames {
450			_, rootTreeHash, refErr := s.GetRefState(refName)
451			if refErr != nil {
452				if errors.Is(refErr, plumbing.ErrReferenceNotFound) {
453					continue
454				}
455				return nil, fmt.Errorf("read %s: %w", refName, refErr)
456			}
457			rootTree, treeErr := s.repo.TreeObject(rootTreeHash)
458			if treeErr != nil {
459				return nil, fmt.Errorf("read %s root tree: %w", refName, treeErr)
460			}
461			keys, err := s.listFullSessionsInTree(rootTree)
462			if err != nil {
463				return nil, fmt.Errorf("walk %s: %w", refName, err)
464			}
465			for _, key := range keys {
466				index[key] = struct{}{}
467			}
468		}
469		return index, nil
470	}
471	
472	func (s *V2GitStore) listFullSessionsInTree(rootTree *object.Tree) ([]string, error) {
473		var keys []string
474		for _, shardEntry := range rootTree.Entries {
475			if shardEntry.Mode != filemode.Dir || len(shardEntry.Name) != 2 {
476				continue
477			}
478			shardTree, err := s.repo.TreeObject(shardEntry.Hash)
479			if err != nil {
480				return nil, fmt.Errorf("read shard %s: %w", shardEntry.Name, err)
481			}
482			for _, cpEntry := range shardTree.Entries {
483				if cpEntry.Mode != filemode.Dir {
484					continue
485				}
486				cpTree, err := s.repo.TreeObject(cpEntry.Hash)
487				if err != nil {
488					return nil, fmt.Errorf("read checkpoint tree %s/%s: %w", shardEntry.Name, cpEntry.Name, err)
489				}
490				cpid := id.CheckpointID(shardEntry.Name + cpEntry.Name)
491				for _, sessionEntry := range cpTree.Entries {
492					if sessionEntry.Mode != filemode.Dir {
493						continue
494					}
495					sessionIdx, atoiErr := strconv.Atoi(sessionEntry.Name)
496					if atoiErr != nil {
497						continue
498					}
499					sessionTree, err := s.repo.TreeObject(sessionEntry.Hash)
500					if err != nil {
501						return nil, fmt.Errorf("read session tree %s/%s/%d: %w", shardEntry.Name, cpEntry.Name, sessionIdx, err)
502					}
503					if !sessionHasCompleteFullArtifacts(sessionTree.Entries) {
504						continue
505					}
506					keys = append(keys, fullArtifactsIndexKey(cpid, sessionIdx))
507				}
508			}
509		}
510		return keys, nil
511	}
512	
513	func sessionHasCompleteFullArtifacts(entries []object.TreeEntry) bool {
514		hasTranscript := false
515		hasHash := false
516		for _, entry := range entries {
517			switch {
518			case entry.Name == paths.V2RawTranscriptFileName,
519				strings.HasPrefix(entry.Name, paths.V2RawTranscriptFileName+"."):
520				hasTranscript = true
521			case entry.Name == paths.V2RawTranscriptHashFileName:
522				hasHash = true
523			}
524		}
525		return hasTranscript && hasHash
526	}
