528	func (s *V2GitStore) fullRefSearchOrder() ([]plumbing.ReferenceName, error) {
529		refNames := []plumbing.ReferenceName{plumbing.ReferenceName(paths.V2FullCurrentRefName)}
530	
531		archived, err := s.ListArchivedGenerations()
532		if err != nil {
533			return nil, err
534		}
535		for i := len(archived) - 1; i >= 0; i-- {
536			refNames = append(refNames, plumbing.ReferenceName(paths.V2FullRefPrefix+archived[i]))
537		}
538	
539		return refNames, nil
540	}
