542	func (s *V2GitStore) inspectFullSessionArtifacts(refName plumbing.ReferenceName, checkpointID id.CheckpointID, sessionIndex int) (fullSessionArtifacts, error) {
543		_, rootTreeHash, err := s.GetRefState(refName)
544		if err != nil {
545			if errors.Is(err, plumbing.ErrReferenceNotFound) {
546				return fullSessionArtifacts{}, nil
547			}
548			return fullSessionArtifacts{}, err
549		}
550	
551		rootTree, err := s.repo.TreeObject(rootTreeHash)
552		if err != nil {
553			return fullSessionArtifacts{}, fmt.Errorf("failed to read %s tree: %w", refName, err)
554		}
555	
556		sessionPath := fmt.Sprintf("%s/%d", checkpointID.Path(), sessionIndex)
557		sessionTree, err := rootTree.Tree(sessionPath)
558		if err != nil {
559			if errors.Is(err, object.ErrDirectoryNotFound) {
560				return fullSessionArtifacts{}, nil
561			}
562			return fullSessionArtifacts{}, fmt.Errorf("failed to read %s session tree %s: %w", refName, sessionPath, err)
563		}
564	
565		artifacts := fullSessionArtifacts{RefName: refName, Found: true}
566		for _, entry := range sessionTree.Entries {
567			switch {
568			case entry.Name == paths.V2RawTranscriptFileName:
569				artifacts.HasTranscript = true
570			case strings.HasPrefix(entry.Name, paths.V2RawTranscriptFileName+"."):
571				artifacts.HasTranscript = true
572			case entry.Name == paths.V2RawTranscriptHashFileName:
573				artifacts.HasHash = true
574			}
575		}
576	
577		return artifacts, nil
578	}
