580	// updateCommittedMain updates prompts and compact transcript on the /main ref for an existing checkpoint.
581	// Returns the session index for coordination with /full/current.
582	func (s *V2GitStore) updateCommittedMain(ctx context.Context, opts UpdateCommittedOptions) (int, error) {
583		refName := plumbing.ReferenceName(paths.V2MainRefName)
584		parentHash, rootTreeHash, err := s.GetRefState(refName)
585		if err != nil {
586			return 0, ErrCheckpointNotFound
587		}
588	
589		basePath := opts.CheckpointID.Path() + "/"
590		checkpointPath := opts.CheckpointID.Path()
591	
592		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
593		if err != nil {
594			return 0, err
595		}
596	
597		rootMetadataPath := basePath + paths.MetadataFileName
598		entry, exists := entries[rootMetadataPath]
599		if !exists {
600			return 0, ErrCheckpointNotFound
601		}
602	
603		summary, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
604		if err != nil {
605			return 0, fmt.Errorf("failed to read checkpoint summary: %w", err)
606		}
607		if len(summary.Sessions) == 0 {
608			return 0, ErrCheckpointNotFound
609		}
610	
611		// Find session index by ID, fall back to latest
612		sessionIndex := s.gs.findSessionIndex(ctx, basePath, summary, entries, opts.SessionID)
613		if sessionIndex >= len(summary.Sessions) {
614			// findSessionIndex returns next-available when not found; fall back to latest
615			sessionIndex = len(summary.Sessions) - 1
616			logging.Debug(ctx, "v2 UpdateCommitted: session ID not found, falling back to latest",
617				slog.String("session_id", opts.SessionID),
618				slog.String("checkpoint_id", string(opts.CheckpointID)),
619				slog.Int("fallback_index", sessionIndex),
620			)
621		}
622	
623		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
624	
625		if len(opts.Prompts) > 0 {
626			promptContent := redact.String(JoinPrompts(opts.Prompts))
627			blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
628			if err != nil {
629				return 0, fmt.Errorf("failed to create prompt blob: %w", err)
630			}
631			entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
632				Name: sessionPath + paths.PromptFileName,
633				Mode: filemode.Regular,
634				Hash: blobHash,
635			}
636		}
637	
638		// Replace compact transcript if provided
639		if len(opts.CompactTranscript) > 0 {
640			blobHash, err := CreateBlobFromContent(s.repo, opts.CompactTranscript)
641			if err != nil {
642				return 0, fmt.Errorf("failed to create compact transcript blob: %w", err)
643			}
644			entries[sessionPath+paths.CompactTranscriptFileName] = object.TreeEntry{
645				Name: sessionPath + paths.CompactTranscriptFileName,
646				Mode: filemode.Regular,
647				Hash: blobHash,
648			}
649	
650			if err := s.writeCompactTranscriptHash(opts.CompactTranscript, sessionPath, entries); err != nil {
651				return 0, fmt.Errorf("failed to write compact transcript hash: %w", err)
652			}
653	
654			// Keep root checkpoint summary in sync with compact artifact paths.
655			if sessionIndex >= 0 && sessionIndex < len(summary.Sessions) {
656				summary.Sessions[sessionIndex].Transcript = "/" + sessionPath + paths.CompactTranscriptFileName
657				summary.Sessions[sessionIndex].ContentHash = "/" + sessionPath + paths.CompactTranscriptHashFileName
658	
659				summaryBytes, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
660				if err != nil {
661					return 0, fmt.Errorf("failed to marshal checkpoint summary: %w", err)
662				}
663				summaryHash, err := CreateBlobFromContent(s.repo, summaryBytes)
664				if err != nil {
665					return 0, fmt.Errorf("failed to create checkpoint summary blob: %w", err)
666				}
667				entries[rootMetadataPath] = object.TreeEntry{
668					Name: rootMetadataPath,
669					Mode: filemode.Regular,
670					Hash: summaryHash,
671				}
672			}
673		}
674	
675		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
676		if err != nil {
677			return 0, err
678		}
679	
680		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
681		commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
682		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail); err != nil {
683			return 0, err
684		}
685	
686		return sessionIndex, nil
687	}
