689	// updateCommittedFullTranscript replaces the transcript for a specific checkpoint
690	// on the /full/* ref where that checkpoint session already lives, while
691	// preserving other checkpoints' transcripts in the tree. If the session has no
692	// full-transcript artifacts yet, it writes to /full/current.
693	func (s *V2GitStore) updateCommittedFullTranscript(ctx context.Context, opts UpdateCommittedOptions, sessionIndex int) error {
694		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
695	
696		existing, findErr := s.findFullSessionArtifacts(opts.CheckpointID, sessionIndex)
697		if findErr != nil {
698			return findErr
699		}
700		if existing.Found {
701			refName = existing.RefName
702		}
703	
704		if refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
705			if err := s.ensureRef(ctx, refName); err != nil {
706				return fmt.Errorf("failed to ensure /full/current ref: %w", err)
707			}
708		}
709	
710		parentHash, rootTreeHash, err := s.GetRefState(refName)
711		if err != nil {
712			return err
713		}
714	
715		basePath := opts.CheckpointID.Path() + "/"
716		checkpointPath := opts.CheckpointID.Path()
717		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
718	
719		// Read existing entries and replace transcript for this checkpoint only
720		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
721		if err != nil {
722			return err
723		}
724	
725		// Ignore precompute if invariants are violated — fall back to fresh chunking.
726		precomputed := opts.PrecomputedBlobs
727		if precomputed != nil && !precomputed.isUsable() {
728			precomputed = nil
729		}
730	
731		// Short-circuit: if the existing raw_transcript_hash.txt already matches
732		// the new transcript's sha256, the existing chunk entries represent the
733		// same content — preserve them and skip chunking + zlib.
734		rawTranscriptPath := sessionPath + paths.V2RawTranscriptFileName
735		rawHashPath := sessionPath + paths.V2RawTranscriptHashFileName
736		var newContentHash string
737		if precomputed != nil {
738			newContentHash = precomputed.ContentHash
739		} else {
740			newContentHash = fmt.Sprintf("sha256:%x", sha256.Sum256(opts.Transcript.Bytes()))
741		}
742		if existing, ok := entries[rawHashPath]; ok {
743			if blob, err := s.repo.BlobObject(existing.Hash); err == nil {
744				if rdr, rerr := blob.Reader(); rerr == nil {
745					existingHash, readErr := io.ReadAll(rdr)
746					_ = rdr.Close()
747					if readErr == nil && string(existingHash) == newContentHash {
748						// Content unchanged — skip tree surgery and ref advance to
749						// avoid a no-op commit on /full/current. The existing ref
750						// already references the correct tree.
751						return nil
752					}
753				}
754			}
755		}
756	
757		// Clear existing transcript artifacts for this session path before writing new ones.
758		// Preserve non-transcript metadata under the same session (e.g., tasks/*).
759		for key := range entries {
760			switch {
761			case key == rawTranscriptPath:
762				delete(entries, key)
763			case strings.HasPrefix(key, rawTranscriptPath+"."):
764				delete(entries, key)
765			case key == rawHashPath:
766				delete(entries, key)
767			}
768		}
769	
770		if err := s.writeTranscriptBlobs(ctx, opts.Transcript, opts.Agent, precomputed, sessionPath, entries); err != nil {
771			return err
772		}
773	
774		if err := s.writeContentHashFromPrecompute(newContentHash, precomputed, sessionPath, entries); err != nil {
775			return err
776		}
777	
778		// Splice into existing root tree (preserves other checkpoints' transcripts)
779		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
780		if err != nil {
781			return err
782		}
783	
784		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
785		commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
786		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail); err != nil {
787			return err
788		}
789	
790		if refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
791			s.rotateCurrentIfNeeded(ctx, newTreeHash)
792		}
793	
794		return nil
795	}
