797	// writeCommittedMain writes metadata entries to the /main ref.
798	// This includes session metadata and prompts — but NOT the raw transcript
799	// (raw_transcript) or content hash (raw_transcript_hash.txt), which go to /full/current.
800	// Returns the session index used, so the caller can pass it to writeCommittedFullTranscript.
801	func (s *V2GitStore) writeCommittedMain(ctx context.Context, opts WriteCommittedOptions) (int, error) {
802		refName := plumbing.ReferenceName(paths.V2MainRefName)
803		if err := s.ensureRef(ctx, refName); err != nil {
804			return 0, fmt.Errorf("failed to ensure /main ref: %w", err)
805		}
806	
807		parentHash, rootTreeHash, err := s.GetRefState(refName)
808		if err != nil {
809			return 0, err
810		}
811	
812		basePath := opts.CheckpointID.Path() + "/"
813		checkpointPath := opts.CheckpointID.Path()
814	
815		// Read existing entries at this checkpoint's shard path
816		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
817		if err != nil {
818			return 0, err
819		}
820	
821		// Build main session entries (metadata, prompts — no transcript or content hash)
822		sessionIndex, err := s.writeMainCheckpointEntries(ctx, opts, basePath, entries)
823		if err != nil {
824			return 0, err
825		}
826	
827		// Splice entries into root tree
828		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
829		if err != nil {
830			return 0, err
831		}
832	
833		commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
834		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
835			return 0, err
836		}
837		return sessionIndex, nil
838	}
