840	// writeMainCheckpointEntries orchestrates writing session data to the /main ref.
841	// It mirrors GitStore.writeStandardCheckpointEntries but excludes raw transcript blobs.
842	// Returns the session index used, for coordination with writeCommittedFullTranscript.
843	func (s *V2GitStore) writeMainCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (int, error) {
844		// Read existing summary to get current session count
845		var existingSummary *CheckpointSummary
846		metadataPath := basePath + paths.MetadataFileName
847		if entry, exists := entries[metadataPath]; exists {
848			existing, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
849			if err == nil {
850				existingSummary = existing
851			}
852		}
853	
854		// Determine session index
855		sessionIndex := s.gs.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
856	
857		// Refuse if slot 0 already holds metadata for a DIFFERENT session ID.
858		// Mirrors GitStore.writeStandardCheckpointEntries: findSessionIndex only
859		// picks slot 0 when existingSummary is nil or when the summary claims slot 0
860		// belongs to us, so the actual tree holding session-0 metadata for someone
861		// else is a corruption / stale-summary shape. Read BEFORE
862		// writeMainSessionToSubdirectory clears the subtree, or we'd only ever see
863		// our own write.
864		if sessionIndex == 0 {
865			if entry, exists := entries[fmt.Sprintf("%s0/%s", basePath, paths.MetadataFileName)]; exists {
866				if existingMeta, readErr := s.gs.readMetadataFromBlob(entry.Hash); readErr == nil && existingMeta.SessionID != opts.SessionID {
867					logging.Error(ctx, "refusing v2 checkpoint write: session 0 holds a different sessionID",
868						slog.String("checkpoint_id", opts.CheckpointID.String()),
869						slog.String("existing_session_id", existingMeta.SessionID),
870						slog.String("write_session_id", opts.SessionID),
871						slog.Bool("existing_summary_nil", existingSummary == nil))
872					return 0, fmt.Errorf(
873						"refusing to overwrite session 0 of checkpoint %s: existing session ID %q differs from write session ID %q. The v2 checkpoint tree is inconsistent (session 0 belongs to a different session than this write claims). No automated repair exists for this shape — please report it along with the output of `git ls-tree %s %s/`",
874						opts.CheckpointID, existingMeta.SessionID, opts.SessionID, paths.V2MainRefName, opts.CheckpointID.Path(),
875					)
876				}
877			}
878		}
879	
880		// Write session files (metadata and prompts — no transcript or content hash)
881		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
882		sessionFilePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
883		if err != nil {
884			return 0, err
885		}
886	
887		// Build the sessions array
888		var sessions []SessionFilePaths
889		if existingSummary != nil {
890			sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
891			copy(sessions, existingSummary.Sessions)
892		} else {
893			sessions = make([]SessionFilePaths, 1)
894		}
895		sessions[sessionIndex] = sessionFilePaths
896	
897		// Write root CheckpointSummary
898		if err := s.gs.writeCheckpointSummary(opts, basePath, entries, sessions); err != nil {
899			return 0, err
900		}
901		return sessionIndex, nil
902	}
903	
904	// writeMainSessionToSubdirectory writes a single session's metadata, prompts,
905	// and compact transcript to a session subdirectory (0/, 1/, 2/, … indexed by
906	// session order within the checkpoint). The raw transcript (raw_transcript) and its
907	// content hash (raw_transcript_hash.txt) go to /full/current, not here.
908	func (s *V2GitStore) writeMainSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
909		filePaths := SessionFilePaths{}
910	
911		// Clear existing entries at this session path
912		for key := range entries {
913			if strings.HasPrefix(key, sessionPath) {
914				delete(entries, key)
915			}
916		}
917	
918		// Write prompts
919		if len(opts.Prompts) > 0 {
920			promptContent := redact.String(JoinPrompts(opts.Prompts))
921			blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
922			if err != nil {
923				return filePaths, err
924			}
925			entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
926				Name: sessionPath + paths.PromptFileName,
927				Mode: filemode.Regular,
928				Hash: blobHash,
929			}
930			filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
931		}
932	
933		// Write compact transcript (transcript.jsonl) + hash if provided
934		if len(opts.CompactTranscript) > 0 {
935			blobHash, err := CreateBlobFromContent(s.repo, opts.CompactTranscript)
936			if err != nil {
937				return filePaths, fmt.Errorf("failed to create compact transcript blob: %w", err)
938			}
939			entries[sessionPath+paths.CompactTranscriptFileName] = object.TreeEntry{
940				Name: sessionPath + paths.CompactTranscriptFileName,
941				Mode: filemode.Regular,
942				Hash: blobHash,
943			}
944			filePaths.Transcript = "/" + sessionPath + paths.CompactTranscriptFileName
945	
946			if err := s.writeCompactTranscriptHash(opts.CompactTranscript, sessionPath, entries); err != nil {
947				return filePaths, fmt.Errorf("failed to write compact transcript hash: %w", err)
948			}
949			filePaths.ContentHash = "/" + sessionPath + paths.CompactTranscriptHashFileName
950		}
951	
952		// Write session metadata
953		sessionMetadata := CommittedMetadata{
954			CheckpointID:                opts.CheckpointID,
955			SessionID:                   opts.SessionID,
956			Strategy:                    opts.Strategy,
957			CreatedAt:                   checkpointCreatedAt(opts),
958			Branch:                      opts.Branch,
959			CheckpointsCount:            opts.CheckpointsCount,
960			FilesTouched:                opts.FilesTouched,
961			Agent:                       opts.Agent,
962			Model:                       opts.Model,
963			TurnID:                      opts.TurnID,
964			IsTask:                      opts.IsTask,
965			ToolUseID:                   opts.ToolUseID,
966			TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
967			CheckpointTranscriptStart:   opts.CompactTranscriptStart,
968			TokenUsage:                  opts.TokenUsage,
969			SessionMetrics:              opts.SessionMetrics,
970			InitialAttribution:          opts.InitialAttribution,
971			PromptAttributions:          opts.PromptAttributionsJSON,
972			Summary:                     redactSummary(opts.Summary),
973			CLIVersion:                  versioninfo.Version,
974			Kind:                        opts.Kind,
975			ReviewSkills:                opts.ReviewSkills,
976			ReviewPrompt:                opts.ReviewPrompt,
977		}
978	
979		metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
980		if err != nil {
981			return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
982		}
983		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
984		if err != nil {
985			return filePaths, err
986		}
987		entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
988			Name: sessionPath + paths.MetadataFileName,
989			Mode: filemode.Regular,
990			Hash: metadataHash,
991		}
992		filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
993	
994		return filePaths, nil
995	}
