997	// writeCompactTranscriptHash computes and writes the SHA-256 hash of the compact transcript.
998	func (s *V2GitStore) writeCompactTranscriptHash(compactTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
999		hash := fmt.Sprintf("sha256:%x", sha256.Sum256(compactTranscript))
1000		blobHash, err := CreateBlobFromContent(s.repo, []byte(hash))
1001		if err != nil {
1002			return err
1003		}
1004		entries[sessionPath+paths.CompactTranscriptHashFileName] = object.TreeEntry{
1005			Name: sessionPath + paths.CompactTranscriptHashFileName,
1006			Mode: filemode.Regular,
1007			Hash: blobHash,
1008		}
1009		return nil
1010	}
