1012	// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
1013	// Transcripts accumulate across checkpoints — each write splices into the existing
1014	// tree. Generation metadata (generation.json) at the tree root is updated on every
1015	// write with the new checkpoint ID and timestamps.
1016	//
1017	// sessionIndex is the session slot (0-based), determined by the caller to stay
1018	// consistent with the /main ref's session numbering.
1019	// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
1020	func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
1021		transcript := opts.Transcript
1022	
1023		// TranscriptPath fallback: data read from disk is an untrusted source,
1024		// so we redact it here. The in-memory path (opts.Transcript) is already
1025		// pre-redacted by the caller.
1026		if transcript.Len() == 0 && opts.TranscriptPath != "" {
1027			rawData, readErr := os.ReadFile(opts.TranscriptPath)
1028			if readErr != nil {
1029				rawData = nil
1030			}
1031			if len(rawData) > 0 {
1032				redacted, redactErr := redact.JSONLBytes(rawData)
1033				if redactErr != nil {
1034					return fmt.Errorf("failed to redact transcript from file: %w", redactErr)
1035				}
1036				transcript = redacted
1037			}
1038		}
1039		if transcript.Len() == 0 {
1040			return nil // No transcript to write
1041		}
1042	
1043		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
1044		if err := s.ensureRef(ctx, refName); err != nil {
1045			return fmt.Errorf("failed to ensure /full/current ref: %w", err)
1046		}
1047	
1048		parentHash, rootTreeHash, err := s.GetRefState(refName)
1049		if err != nil {
1050			return err
1051		}
1052	
1053		basePath := opts.CheckpointID.Path() + "/"
1054		checkpointPath := opts.CheckpointID.Path()
1055		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
1056	
1057		// Read existing entries at this checkpoint's shard path
1058		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
1059		if err != nil {
1060			return err
1061		}
1062	
1063		// Clear existing entries at this session path before writing new ones
1064		for key := range entries {
1065			if strings.HasPrefix(key, sessionPath) {
1066				delete(entries, key)
1067			}
1068		}
1069	
1070		if err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, nil, sessionPath, entries); err != nil {
1071			return err
1072		}
1073	
1074		contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript.Bytes()))
1075		if err := s.writeContentHashFromPrecompute(contentHash, nil, sessionPath, entries); err != nil {
1076			return err
1077		}
1078	
1079		// Splice checkpoint data into the root tree (preserves other checkpoints' transcripts)
1080		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
1081		if err != nil {
1082			return err
1083		}
1084	
1085		commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
1086		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
1087			return err
1088		}
1089	
1090		s.rotateCurrentIfNeeded(ctx, newTreeHash)
1091		return nil
1092	}
1093	
1094	func (s *V2GitStore) rotateCurrentIfNeeded(ctx context.Context, treeHash plumbing.Hash) {
1095		checkpointCount, countErr := s.CountCheckpointsInTree(treeHash)
1096		if countErr != nil {
1097			logging.Warn(ctx, "failed to count checkpoints for rotation check",
1098				slog.String("error", countErr.Error()),
1099			)
1100			return
1101		}
1102		if checkpointCount < s.maxCheckpoints() {
1103			return
1104		}
1105		if rotErr := s.rotateGeneration(ctx); rotErr != nil {
1106			logging.Warn(ctx, "generation rotation failed",
1107				slog.String("error", rotErr.Error()),
1108				slog.Int("checkpoint_count", checkpointCount),
1109			)
1110			// Non-fatal: rotation failure doesn't invalidate the write
1111		}
1112	}
1113	
1114	// writeTranscriptBlobs writes pre-redacted, chunked transcript blobs to entries.
1115	// When precomputed is non-nil, reuses its chunk blob hashes and skips both
1116	// ChunkTranscript and CreateBlobFromContent.
1117	func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript redact.RedactedBytes, agentType types.AgentType, precomputed *PrecomputedTranscriptBlobs, sessionPath string, entries map[string]object.TreeEntry) error {
1118		var chunkHashes []plumbing.Hash
1119		if precomputed != nil {
1120			chunkHashes = precomputed.ChunkHashes
1121		} else {
1122			chunks, err := chunkTranscript(ctx, transcript.Bytes(), agentType)
1123			if err != nil {
1124				return fmt.Errorf("failed to chunk transcript: %w", err)
1125			}
